class SearchIndex {
  constructor(items = [], options = {}) {
    this.searchable = options.searchable || []
    this.items = []
    const fieldSet = new Set()

    items.forEach(data => {
      for (const key in data) fieldSet.add(key)
      this.items.push(this._prepareData(data, this.searchable))
    })

    this.fields = Array.from(fieldSet)
  }

  search(query) {
    const filters = this._parseQuery(query)
    if (filters.length === 0) return this.items.map(h => h._raw)

    const hits = []
    const itemCount = this.items.length
    const filterCount = filters.length

    for (let i = 0; i < itemCount; i++) {
      const item = this.items[i]
      let isMatch = true

      for (let j = 0; j < filterCount; j++) {
        const f = filters[j]
        const targetValue = item._searchable[f.field]

        if (targetValue === undefined) {
          if (!f.exclude) {
            isMatch = false
            break
          }
          continue
        }

        const isMatchValue =
          f.type === 'num'
            ? f.op === '<'
              ? targetValue < f.val
              : targetValue > f.val
            : f.regex.test(targetValue)

        if (f.exclude ? isMatchValue : !isMatchValue) {
          isMatch = false
          break
        }
      }

      if (isMatch) hits.push(item._raw)
    }

    return hits
  }

  _prepareData(rawData, searchableAttributes) {
    const data = { _raw: rawData, _searchable: {} }

    const keysToIndex =
      searchableAttributes.length > 0 ? searchableAttributes : Object.keys(rawData)

    let globalKey = ''

    for (const key in rawData) {
      const value = rawData[key]
      if (value === undefined || value === null) continue

      const isSearchable = searchableAttributes.length === 0 || searchableAttributes.includes(key)
      let normalizedValue = value

      if (Array.isArray(value)) {
        normalizedValue = value.map(el => this._normalize(el)).join(',')
      } else if (typeof value === 'string') {
        normalizedValue = this._normalize(value)
      }

      if (isSearchable) {
        data._searchable[key] = normalizedValue
        if (keysToIndex.includes(key)) {
          globalKey += `|${normalizedValue}`
        }
      }
    }

    data._searchable._ = globalKey + '|'
    return data
  }

  _normalize(val) {
    return String(val).trim().toLowerCase()
  }

  _parseQuery(query) {
    if (!query) return []

    const parts = query.match(/(".*?"|[^"\s]+)+(?=\s*|\s*$)/g) || []
    const filters = []

    for (let rawValue of parts) {
      let exclude = false
      let field = '_'
      let value = rawValue

      if (value.includes(':')) {
        const separatorIndex = value.indexOf(':')
        let qualifier = value.substring(0, separatorIndex)
        if (qualifier.startsWith('-')) {
          exclude = true
          qualifier = qualifier.slice(1)
        }

        if (this.searchable.includes(qualifier) || this.fields.includes(qualifier)) {
          field = qualifier
          value = value.substring(separatorIndex + 1)
        }
      }

      value = value.replace(/"/g, '').toLowerCase()
      if (!value) continue

      const filter = { field, exclude }

      if (value.startsWith('<') || value.startsWith('>')) {
        filter.type = 'num'
        filter.op = value[0]
        filter.val = parseFloat(value.substring(1))
      } else if (value.startsWith('/') && value.endsWith('/')) {
        filter.type = 'reg'
        filter.regex = new RegExp(value.slice(1, -1), 'i')
      } else {
        filter.type = 'reg'
        const pattern = value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&').replace(/,/g, '|')
        filter.regex = new RegExp(pattern, 'i')
      }

      filters.push(filter)
    }

    return filters
  }
}

function createIndex(items, options) {
  return new SearchIndex(items, options)
}

export default { createIndex }
